class JRentalService {
    private final java.util.Map<JRentalId, JRental> rentals;

    JRentalService(Map<JRentalId, JRental> rentals) {
        this.rentals = rentals;
    }

    float amountOwed(JRentalId id){
        JRental rental = rentals.get(id);
        return effectiveRentedDays(rental);
    }

    private float effectiveRentedDays(JRental rental){
        return switch (rental.type()){
            case "regular" -> rental.daysRented().rawValue() * 2f;
            default -> rental.daysRented().rawValue() * 10f;
        };
    }
}

sealed interface JRental {
}

record JRegularRental(JRentalId id, JDay daysRented) implements JRental{}
record JNewRental(JRentalId id, JDay daysRented) implements JRental{}

class JRental {

    private final String id;
    private final String type;
    private final Float daysRented;

    JRental(String id, String type, Float daysRented){
        this.id = id;
        this.type = type;
        this.daysRented = daysRented;
    }

    public String id() {
        return id;
    }

    public String type() {
        return type;
    }

    public Float daysRented(){
        return this.daysRented;
    }
}

record JDay(float rawValue){

    JDay {
        assert rawValue >= 0;
    }
}

data class KDay(val rawValue: Float){

    init {
        require(rawValue >= 0)
    }
}

class KRentalService(private val rentals: Map<KRentalId, KRental>) {

    fun amountOwed(id: KRentalId): Float {
        val rental: KRental = rentals.get(id)
        return effectiveRentedDays(rental)
    }

    private fun effectiveRentedDays(rental: KRental): Float {
        return when(rental.type) {
            "regular" -> rental.daysRented.rawValue * 2f
            "new" -> rental.daysRented.rawValue * 10f
        }
    }
}

// pure get property
val weeksRented: Float
    get() = this.days / 7

// get and set property
var monthsRented: String
    get() = this.days / 30
    set(value) {
        this.days = value * 30
    }

class JRentalBuilder {
    // assumption here is that this is for test data initiation
    String id = "1";
    String type = "regular";
    Float daysRented = 0.0f;

    JRental build(){
        return new JRental(id, type, daysRented);
    }

    static JRental aRental(java.util.function.Consumer<JRentalBuilder> init){
        var builder = new JRentalBuilder();
        init.accept(builder);

        return builder.build();
    }
}

class KRentalBuilder {
    // assumption here is that this builder would be for test data usage
    var type: String = "regular"
    var daysRented: Float = 0.0f

    fun build() = KRental(type, daysRented)
}

fun aRental(init: KRentalBuilder.() -> Unit): KRental {
    val builder = KRentalBuilder();
    init(builder)
    return builder.build()
}

var daysRented: Float = 0.0f
    set(value) {
        // check invariants
        require(value > 0.0f)
        field = value
    }

val newRental = rental.copy(
    type = "childrens"
)

// once derived record creation JEP is finished
var newRental = rental with {
    type = "childrens";
}

var regularRental = new JRental("1", "regular", 1.0f);
var childrensRental = new JRental("1", "childrens", 1.0f);
System.out.println("Is rental is equal when values match? "+rental.equals(regularRental));
System.out.println("Is rental is equal when values do not match? "+rental.equals(childrensRental));

